:where([data-moru-registry]) .ui-native-select {
  font-family: var(--ui-font-family, inherit);
  color: var(--ui-text, #171717);
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  letter-spacing: var(--ui-type-label-letter-spacing, -0.01em);
  box-sizing: border-box;
}
:where([data-moru-registry]) .ui-native-select {
  --ui-size-height: var(--ui-control-height-md, var(--ui-control-height, 40px));
  --ui-size-padding-x: var(--ui-control-padding-x-md, 12px);
  --ui-size-icon: var(--ui-icon-size-md, 16px);
  --ui-resolved-control-height: max(
    var(--ui-size-height),
    calc(
      max(
          var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45),
          var(--ui-size-icon)
        ) +
        var(--ui-border-width, 1px) * 2 + var(--ui-space, 4px) * 2
    )
  );
}
:where([data-moru-registry]) .ui-native-select[data-size='sm'] {
  --ui-size-height: var(--ui-control-height-sm, 32px);
  --ui-size-padding-x: var(--ui-control-padding-x-sm, 10px);
  --ui-size-icon: var(--ui-icon-size-sm, 14px);
}
:where([data-moru-registry]) .ui-native-select[data-size='lg'] {
  --ui-size-height: var(--ui-control-height-lg, 48px);
  --ui-size-padding-x: var(--ui-control-padding-x-lg, 16px);
  --ui-size-icon: var(--ui-icon-size-lg, 18px);
}
:where([data-moru-registry]) .ui-native-select-wrap {
  --ui-native-padding: var(--ui-control-padding-x-md, 14px);
  /* Layout comes from .ui-control-loading-wrap on the same element. */
  width: 100%;
  position: relative;
  min-width: 0;
}
:where([data-moru-registry]) .ui-native-select-wrap[data-size='sm'] {
  --ui-native-padding: var(--ui-control-padding-x-sm, 10px);
}
:where([data-moru-registry]) .ui-native-select-wrap[data-size='lg'] {
  --ui-native-padding: var(--ui-control-padding-x-lg, 18px);
}
:where([data-moru-registry]) .ui-native-select {
  width: 100%;
  min-width: 0;
  appearance: none;
  height: var(--ui-resolved-control-height);
  min-height: var(--ui-resolved-control-height);
  padding-block: 0;
  padding-inline: var(--ui-size-padding-x)
    calc(var(--ui-size-padding-x) + var(--ui-size-icon) + var(--ui-control-gap, 8px));
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-input-bg, #f0f0ed);
  cursor: pointer;
  transition:
    border-color var(--ui-duration, 150ms),
    box-shadow var(--ui-duration, 150ms);
  border-color: transparent;
  font-weight: var(--ui-type-body-weight, 400);
}
:where([data-moru-registry]) .ui-native-select-wrap > svg {
  position: absolute;
  pointer-events: none;
  inset-inline-end: var(--ui-native-padding);
  top: 50%;
  transform: translateY(-50%);
  width: var(--ui-size-icon, 16px);
  height: var(--ui-size-icon, 16px);
  color: var(--ui-muted, #6e6e6b);
}
:where([data-moru-registry]) .ui-native-select option,
:where([data-moru-registry]) .ui-native-select optgroup {
  background: var(--ui-surface, #fff);
  color: var(--ui-text, #171717);
}
:where([data-moru-registry]) .ui-native-select:hover:not(:disabled) {
  background: color-mix(in srgb, var(--ui-input-bg, #f0f0ed) 94%, var(--ui-text, #171717));
  border-color: var(--ui-border, #e8e8e4);
}
:where([data-moru-registry]) .ui-native-select:focus-visible {
  outline: 2px solid var(--ui-focus-ring, var(--ui-ring, #181818));
  outline-offset: 3px;
}
:where([data-moru-registry]) .ui-native-select[aria-invalid='true'] {
  border-color: var(--ui-danger, #c14b45);
  background: var(--ui-danger-soft, #f9efef);
  box-shadow: 0 0 0 1px var(--ui-error-ring, var(--ui-danger, #c14b45));
  outline-color: var(--ui-error-ring, var(--ui-danger, #c14b45));
}
:where([data-moru-registry]) .ui-native-select:disabled {
  opacity: 1;
  color: var(--ui-disabled-text);
  background: var(--ui-disabled-bg);
  border-color: var(--ui-disabled-border);
  cursor: not-allowed;
  box-shadow: none;
}
@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-native-select {
    --ui-resolved-control-height: max(
      44px,
      var(--ui-size-height),
      calc(
        max(
            max(16px, var(--ui-type-label-size, 14px)) * var(--ui-type-label-line-height, 1.45),
            var(--ui-size-icon)
          ) +
          var(--ui-border-width, 1px) * 2 + var(--ui-space, 4px) * 2
      )
    );
  }
  :where([data-moru-registry]) .ui-native-select {
    font-size: max(16px, var(--ui-type-label-size, 13px));
  }
}
@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-native-select {
    border: 1px solid ButtonText;
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-native-select {
    transition: none;
  }
}
:where([data-moru-registry]) .ui-native-select[data-loading] {
  cursor: progress;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, type SelectHTMLAttributes } from 'react'
import { Field as BaseField } from '@base-ui/react/field'
import { ChevronDown } from 'lucide-react'
import { cn } from './_lib/cn'
import { mergeDescriptionIds, useFieldContext } from './field-context'
import type { UIState } from './state'
import './controls-shared.css'
import './native-select.css'

export interface NativeSelectOption {
  value: string
  label: string
  disabled?: boolean
}
export type NativeSelectProps = Omit<
  SelectHTMLAttributes<HTMLSelectElement>,
  'size' | 'multiple'
> & {
  size?: 'sm' | 'md' | 'lg'
  loading?: boolean
  previewState?: UIState
  items?: NativeSelectOption[]
  onValueChange?: (value: string) => void
}
export const NativeSelect = forwardRef<HTMLSelectElement, NativeSelectProps>(function NativeSelect(
  {
    size = 'md',
    items,
    children,
    className,
    id,
    disabled,
    loading = false,
    previewState,
    onChange,
    onValueChange,
    'aria-describedby': describedBy,
    'aria-invalid': invalid,
    ...props
  },
  ref,
) {
  const field = useFieldContext()
  const busy = loading || previewState === 'loading'
  const unavailable = disabled || busy || previewState === 'disabled'
  const select = (
    <select
      {...props}
      disabled={unavailable}
      aria-busy={busy || undefined}
      data-loading={busy || undefined}
      ref={ref}
      {...(!field ? { id } : {})}
      className={cn('ui-native-select', className)}
      data-size={size}
      aria-describedby={mergeDescriptionIds(describedBy, field?.describedBy)}
      aria-invalid={previewState === 'error' ? true : (invalid ?? (field?.invalid || undefined))}
      onChange={(event) => {
        if (unavailable) return
        onChange?.(event)
        if (!event.defaultPrevented) onValueChange?.(event.target.value)
      }}
    >
      {items
        ? items.map((item) => (
            <option key={item.value} value={item.value} disabled={item.disabled}>
              {item.label}
            </option>
          ))
        : children}
    </select>
  )
  return (
    <span className="ui-native-select-wrap ui-control-loading-wrap" data-size={size}>
      {field ? (
        <BaseField.Control
          render={select}
          id={id ?? field.controlId}
          disabled={unavailable}
          value={props.value}
          defaultValue={props.defaultValue}
        />
      ) : (
        select
      )}
      {busy ? (
        <span className="ui-control-loading-indicator ui-loading-indicator" aria-hidden="true" />
      ) : (
        <ChevronDown aria-hidden="true" />
      )}
    </span>
  )
})
